import {View,Image,StyleSheet,Text, Pressable} from 'react-native'

const Outdoor_CLG = ({route},{navigation}) => {
    return(
    <View style = {styles.container}>
        <View >
            <Text style = {{color: 'white', fontsize: 50}}>
                Which Sport?
            </Text>
        </View> 
        <View style = {styles.orangebutton}>
            <Text style = {{color: 'black', fontsize: 40}}>
                College : Outdoor
            </Text>
        </View>
        <Pressable>
            <Image
                source={require('/assets/basketBallGame.png')}
                style = {styles.GameButtonStyle}

            />
        </Pressable>
    </View>
    );
    };

    const styles = StyleSheet.create({
        container:{
            flex: 1,
            backgroundColor: 'white'
        },
        navbuttoncontainer:{
            justifyContent: "top",
            alignItems:"center"
        },
        navbutton:{
            height: 100,
            width: 200,
            borderWidth: 20,
            backgroundImage: 'linear-gradient(to right, #3437eb, #eb34d9)',
            justifyContent: "center",
            alignItems:"center"
           
        },
        orangebutton:{
            
            alignItems: "center",
            width: 200,
            height: 100,
            borderRadius: 100,
            borderWidth: 20,
            backgroundImage: 'linear-gradient(to right, #ffde59, #ff914d)',
            

        },
        appdim:{
            height : 1300,
            width: 100
        },
        GameButtonStyle:{

            justifyContent : top,
            height: 500,
            width: 500,
            

        },

     });
    
     export default Outdoor_CLG
